contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool allAccepted = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, ) = caddress.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[i], v));
            if (!ok) {
                allAccepted = false;
                break;
            }
        }

        assert(reverted == !allAccepted);
    }
}

